import java.util.List;

/**
 * A simple model of a Lion.
 * Lions age, move, eat deers/cats/owls/mouse, and die.
 *
 * @version 2022.03.02 
 */
public class Lion extends BreedingAnimal
{
    // Characteristics shared by all Liones (class variables).

    // The age at which a Lion can start to breed.
    private static final int BREEDING_AGE = 10;
    // The age to which a Lion can live.
    private static final int MAX_AGE = 225;
    // The likelihood of a Lion breeding. 
    private static final double BREEDING_PROBABILITY = 0.10;
    // The maximum number of births.
    private static final int MAX_LITTER_SIZE = 5;
    // The food value of a single lion.
    private static final int FOOD_VALUE = 20;
    // number of steps a lion can go before it has to eat again.
    private static final int DEFAULT_FOOD_LEVEL = 275;
    // The starting food level for newborn lions.
    private static final int NEWBORN_FOOD_LEVEL = 40;

    /**
     * Create a Lion. A Lion can be created as a new born (age zero
     * and not hungry) or with a random age and food level.
     * 
     * @param randomAge If true, the Lion will have random age and hunger level.
     * @param field The field currently occupied.
     * @param location The location within the field.
     */
    public Lion(boolean randomAge, Field field, Location location)
    {
        super(field, location);
        initializeAge(randomAge, MAX_AGE);
        initializeFoodLevel(randomAge, DEFAULT_FOOD_LEVEL, NEWBORN_FOOD_LEVEL);
    }

    @Override
    protected int getMaxAge()
    {
        return MAX_AGE;
    }

    @Override
    protected void updateStatus(SimulationStep step)
    {
        decrementFoodLevel();
    }

    /**
     * Look for deer, cat, owl ,mouse adjacent to the current location.
     * Only the first live deer/cat/owl/mouse is eaten.
     * @return Where food was found, or null if it wasn't.
     */
    private Location findFood()
    {
        Location preyLocation = eat(Deer.class);
        if(preyLocation != null) {
            return preyLocation;
        }

        preyLocation = eat(Cat.class);
        if(preyLocation != null) {
            return preyLocation;
        }

        preyLocation = eat(Owl.class);
        if(preyLocation != null) {
            return preyLocation;
        }

        return eat(Mouse.class);
    }

    @Override
    protected int getBreedingAge()
    {
        return BREEDING_AGE;
    }

    @Override
    protected double getBreedingProbability()
    {
        return BREEDING_PROBABILITY;
    }

    @Override
    protected int getMaxLitterSize()
    {
        return MAX_LITTER_SIZE;
    }

    @Override
    protected boolean requiresMate()
    {
        return true;
    }

    @Override
    protected int getMateSearchRadius()
    {
        return 2;
    }

    @Override
    protected Animal createYoung(Field field, Location location)
    {
        return new Lion(false, field, location);
    }

    @Override
    protected void handleAliveStep(List<Organism> newLions, SimulationStep step)
    {
        breed(newLions);
    }

    @Override
    protected Location selectMoveLocation(SimulationStep step)
    {
        if(step.getWeather() == Weather.FOGGY) {
            return null;
        }
        return findFood();
    }

    @Override
    protected boolean shouldMove(SimulationStep step)
    {
        return !step.isNight();
    }

    /**
     * Hunt a specific prey species adjacent to this lion.
     */
    private <T extends Animal> Location eat(Class<T> preyClass)
    {
        return findAdjacentLocation(preyClass, 1, prey -> {
            if(prey.isAlive()) {
                prey.setDead();
                changeFoodLevel(prey.foodValue());
                return true;
            }
            return false;
        });
    }

    /**
     * @return lion's food value.
     */
    public int foodValue()
    {
        return FOOD_VALUE;
    }
}

import java.util.List;
import java.util.Random;

/**
 * A simple model of a mouse.
 * Mice age, move, eat seed, breed, and die.
 *
 * @version 2022.03.02 
 */
public class Mouse extends BreedingAnimal
{
    // Characteristics shared by all mouses (class variables).

    // The age at which a mouse can start to breed.
    private static final int BREEDING_AGE = 5;
    // The age to which a mouse can live.
    private static final int MAX_AGE = 125;
    // The likelihood of a mouse breeding.
    private static final double BREEDING_PROBABILITY = 0.25;
    // The likelihood of a mouse infect by disease.
    private static final double INFECT_PROBABILITY = 0.01;
    // The maximum number of births.
    private static final int MAX_LITTER_SIZE = 10;
    // The food value of a single mouse. In effect, this is the
    // number of steps a mouse can go.
    private static final int DEFAULT_FOOD_LEVEL = 5;
    // A shared random number generator to control breeding.
    private static final Random rand = Randomizer.getRandom();
    // The food value of a single mouse. 
    private static final int FOOD_VALUE = 5;

    // The mouse infected by deisease.
    // 0 - not infect, 1-3 degree of infection.
    private int infect;
    // chance of a mice to recover or deteriorate from disease.
    private static final double recover_probability = 0.3 ;
    private static final double deteriorate_probability = 0.15 ;
    /**
     * Create a new mouse. A mouse may be created with age
     * zero (a new born) or with a random age.
     * 
     * @param randomAge If true, the mouse will have a random age.
     * @param field The field currently occupied.
     * @param location The location within the field.
     */
    public Mouse(boolean randomAge, Field field, Location location)
    {
        super(field, location);
        initializeAge(randomAge, MAX_AGE);
        initializeFoodLevel(randomAge, DEFAULT_FOOD_LEVEL, DEFAULT_FOOD_LEVEL);
    }

    @Override
    protected int getMaxAge()
    {
        return MAX_AGE;
    }

    @Override
    protected int getBreedingAge()
    {
        return BREEDING_AGE;
    }

    @Override
    protected double getBreedingProbability()
    {
        return BREEDING_PROBABILITY;
    }

    @Override
    protected int getMaxLitterSize()
    {
        return MAX_LITTER_SIZE;
    }

    @Override
    protected Animal createYoung(Field field, Location location)
    {
        return new Mouse(false, field, location);
    }

    @Override
    protected void updateStatusAfterBurn(SimulationStep step)
    {
        checkInfectLevel();
    }

    @Override
    protected void handleAliveStep(List<Organism> newMice, SimulationStep step)
    {
        if(getInfected() != 0) {
            forEachAdjacent(Mouse.class, 1, mouse -> {
                if(mouse.getInfected() == 0) {
                    mouse.infect();
                }
            });
            diseaseRecover();
        }
        else {
            breed(newMice);
            infect();
        }
    }

    /**
     * Look for grass adjacent to the current location.
     * Only the first seed (belong to grass) will be located.
     * @return Where food was found, or null if it wasn't.
     */
    @Override
    protected Location selectMoveLocation(SimulationStep step)
    {
        return findFood();
    }

    private Location findFood()
    {
        return findAdjacentLocation(Grass.class, 1, grass -> {
            if(grass.isAlive()) {
                changeFoodLevel(2);
                return true;
            }
            return false;
        });
    }

    /**
     * @return true if the mouse is infected by disease, false otherwise.
     */
    private int getInfected()
    {
        return infect;
    }

    /**
     * A mouse can be infected by disease.
     */
    private void infect()
    {
        if(rand.nextDouble() <= INFECT_PROBABILITY) {
            infect = 1;
        }        
    }
    /**
     * mouse will die from disease when the infect indicator reach 3.
     */
    private void checkInfectLevel()
    {
        if(infect == 3) {
            setDead();
        }
    }

    /**
     * A mouse can recover or deteriorate from disease
     */
    private void diseaseRecover()
    {
        if(rand.nextDouble() <= deteriorate_probability) {
            infect ++ ;
        }  
        else if (rand.nextDouble() <= recover_probability) {
            infect -- ;
        }  
    }

    /**
     * @return mouse's food value.
     */
    public int foodValue()
    {
        return FOOD_VALUE;
    }
}

